SELECT 
  FROM public.agent_runtime_workflow_script_calls
 WHERE tenant_id = #{tenantId}
   AND execution_id = #{executionId}
   AND node_id = #{nodeId}
   AND visit = #{visit}
   AND call_index = #{callIndex}

SELECT 
  FROM public.agent_runtime_workflow_script_calls
 WHERE tenant_id = #{tenantId}
   AND execution_id = #{executionId}
   AND session_id = #{sessionId}
   AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND agent_id = #{agentId}
   AND end_user_id IS NOT DISTINCT FROM #{endUserId}
   AND run_id = #{runId}
   AND state IN ('PREPARED', 'DISPATCHED')
 ORDER BY node_id, visit, call_index

mapper.update:
UPDATE public.agent_runtime_workflow_script_calls
   SET state = 'DISPATCHED',
       dispatched_at = clock_timestamp()
 WHERE tenant_id = #{tenantId}
   AND execution_id = #{executionId}
   AND node_id = #{nodeId}
   AND visit = #{visit}
   AND call_index = #{callIndex}
   AND state = 'PREPARED'

UPDATE public.agent_runtime_workflow_script_calls
   SET state = #{state},
       terminal_fingerprint = #{terminalFingerprint},
       terminal_data = #{terminalData},
       terminal_at = clock_timestamp()
 WHERE tenant_id = #{tenantId}
   AND execution_id = #{executionId}
   AND node_id = #{nodeId}
   AND visit = #{visit}
   AND call_index = #{callIndex}
   AND state = 'DISPATCHED'
